#!/usr/bin/env bash
# gaps-fixed.sh -- regenerate docs/GAPS_FIXED.md from docs/LEDGER.tsv and the audit notes in docs/tracker/ and docs/TODO_2.md.
# Prints one summary line of gap counts (FIXED / VERIFIED / BLOCKED-DATA / STILL OPEN) to stdout.
set -euo pipefail
cd "$(dirname "$0")/.."
python3 - <<'PY'
import csv, glob, os, re
rows = list(csv.DictReader(open('docs/LEDGER.tsv'), delimiter='\t'))
out = ['# Gaps fixed', '',
       'Generated by `scripts/gaps-fixed.sh` from `docs/LEDGER.tsv`, `docs/tracker/*.md` and `docs/TODO_2.md`. Do not edit by hand.', '']
for kind, title in (('pr', 'Upstream pull requests'), ('issue', 'Upstream issues')):
    sel = [r for r in rows if r['kind'] == kind]
    done = [r for r in sel if r['state'] == 'DONE']
    skipped = [r for r in sel if r['state'] == 'SKIPPED']
    out += ['## %s' % title, '', '%d total: %d fixed on master, %d skipped (already present or obsolete), %d open.' %
            (len(sel), len(done), len(skipped), len(sel) - len(done) - len(skipped)), '',
            '| # | Title | State | Commit |', '|---|---|---|---|']
    for r in sorted(sel, key=lambda r: int(r['number'])):
        t = r['title'].replace('|', '/')[:90]
        out.append('| [#%s](%s) | %s | %s | %s |' % (r['number'], r['url'], t, r['state'], ('`%s`' % r['commit']) if r['commit'] else '-'))
    out.append('')

# Status classification. A line counts only if it is a table row or a list item.
ITEM = re.compile(r'^\s*(\||[-*]\s|\d+[.)]\s)')
OPEN = re.compile(r'\bSTILL OPEN\b|\bOPEN\b|\bnot fixed\b|\bstill open\b')
BLOCKED = re.compile(r'\bBLOCKED-DATA\b')
VERIFIED = re.compile(r'\bVERIFIED\b')
FIXED = re.compile(r'\bFIXED\b')
counts = {'FIXED': 0, 'VERIFIED': 0, 'BLOCKED-DATA': 0, 'STILL OPEN': 0}
files = sorted(glob.glob('docs/tracker/*.md')) + ['docs/TODO_2.md']
open_by_file = []
fixed = []
for f in files:
    slug = os.path.basename(f)
    if slug.endswith('.md'):
        slug = slug[:-3]
    still = []
    for line in open(f, encoding='utf-8', errors='replace'):
        s = line.strip()
        if not ITEM.match(s):
            continue
        # Precedence: open > blocked > verified > fixed, so one line is counted once.
        if OPEN.search(s):
            counts['STILL OPEN'] += 1
            still.append(re.sub(r'\s+', ' ', s)[:200])
        elif BLOCKED.search(s):
            counts['BLOCKED-DATA'] += 1
        elif VERIFIED.search(s):
            counts['VERIFIED'] += 1
        elif FIXED.search(s):
            counts['FIXED'] += 1
            fixed.append((slug, re.sub(r'\s+', ' ', s)[:200]))
    if still:
        open_by_file.append((slug, still))

out += ['## Parity audit gaps', '',
        'Audit notes under `docs/tracker/` and `docs/TODO_2.md` record each vanilla gap. Counted lines: FIXED %d, VERIFIED %d, BLOCKED-DATA %d, STILL OPEN %d.' %
        (counts['FIXED'], counts['VERIFIED'], counts['BLOCKED-DATA'], counts['STILL OPEN']), '']
for slug, line in fixed:
    out.append('- `%s`: %s' % (slug, line))
out += ['', '## Still open by file', '']
for slug, lines in open_by_file:
    out += ['### `%s` (%d)' % (slug, len(lines)), '']
    out += ['- %s' % l for l in lines]
    out.append('')
open('docs/GAPS_FIXED.md', 'w').write('\n'.join(out).rstrip('\n') + '\n')
print('gaps: FIXED=%d VERIFIED=%d BLOCKED-DATA=%d STILL-OPEN=%d (%d files)' %
      (counts['FIXED'], counts['VERIFIED'], counts['BLOCKED-DATA'], counts['STILL OPEN'], len(open_by_file)))
PY
